function quickLinks(){return `<div class="quick-modules logistics-quick">${[['schedule','calendar','今日通告','时间、地点与准备'],['travel','car','差旅接送','交通、住宿与集合'],['site','users','现场联络','联系人与进场信息'],['checklists','check','准备清单','妆发、餐食与物品'],['handoff','box','费用交接','票据、借还与留痕']].map(([r,i,t,d])=>`<a class="quick-module" href="#${r}"><span>${icon(i)}</span><b>${t}</b><small>${d}</small></a>`).join('')}</div>`;}
function overview(){const todo=state.preparations.filter(c=>!c.done).length,pendingTravel=state.travel.filter(t=>!['已确认','已完成'].includes(t.status)).length;return `${head('把每一天，安排妥当。','你好，'+esc(currentUser.display_name)+'。先看今天的通告、出行和还没落实的事。',`<span class="head-date"><strong>10 月 23 日</strong> &nbsp; 星期五</span><a class="btn primary" href="#schedule">${icon('calendar','tiny')}查看今日通告</a>`)}<div class="metrics">${metric('今日正式通告',state.events.filter(e=>e.start.startsWith('2026-10-23')).length,'项','calendar','执行信息围绕正式安排组织')}${metric('准备待落实',todo,'项','check','已明确负责人和检查时间')}${metric('出行待确认',pendingTravel,'项','car','需求登记与确认状态分开')}${metric('日程待批准',countPending(),'项','refresh','批准前正式日程保持原样')}</div><div class="grid-main"><div class="stack"><section class="panel"><div class="panel-head"><div><h2>今日执行重点</h2><p class="panel-sub">《回声》片场到场 · 接送、人员与准备事项</p></div>${badge('10 月 23 日','blue')}</div><div class="execution-summary"><div><small>集合出发</small><strong>${esc(state.travel.find(t=>t.id==='tr1')?.time||'待确认')}</strong><span>${esc(state.travel.find(t=>t.id==='tr1')?.meeting||'集合点待确认')}</span></div><div><small>正式到场</small><strong>${fmt(state.events[0].start)}</strong><span>${esc(state.events[0]?.location||'暂无正式地点')}</span></div><div><small>执行统筹</small><strong>林舒</strong><span>统筹车辆、现场与准备</span></div></div><div class="panel-body" style="padding-top:0"><div class="row between mb"><span class="list-title" style="margin:0">还需落实</span><a class="text-btn" href="#checklists">完整清单 ${icon('arrow','tiny')}</a></div>${state.preparations.filter(c=>!c.done).slice(0,3).map(checkRow).join('')}</div></section><div><div class="section-label" style="margin-top:0">后勤执行入口</div>${quickLinks()}</div><section class="panel"><div class="panel-head"><h2>后勤项目</h2><a class="text-btn" href="#projects">全部项目 ${icon('arrow','tiny')}</a></div>${projectRows()}</section><section class="panel"><div class="panel-head"><h2>团队动态</h2></div>${state.audit.length?state.audit.slice(0,3).map(a=>`<div class="activity"><i class="activity-mark"></i><div class="grow"><strong>${esc(a.title)}</strong><p>${esc(a.detail)}</p></div><time>${esc(a.time)}</time></div>`).join(''):'<div class="empty">暂无新的业务动态</div>'}</section></div><aside class="stack">${panel('今日通告',`<div class="mini-agenda">${agenda()}</div>`,`<a class="text-btn" href="#schedule">${icon('arrow','tiny')}</a>`)}${panel('日程变更',teaser(),badge(countPending()+' 待批','amber'))}${panel('待交接物品',`<div class="panel-body">${state.belongings.filter(b=>!['已接收','已归还'].includes(b.status)).map(b=>`<div class="row between"><div><h3>${esc(b.title)}</h3><p class="panel-sub">${esc(b.holder)} → ${esc(b.recipient)}</p></div>${badge(b.status,'amber')}</div>`).join('')||'<p class="muted" style="font-size:10px">当前暂无待交接物品</p>'}<a class="text-btn mt" href="#handoff">查看物品与费用 ${icon('arrow','tiny')}</a></div>`)}</aside></div>`;}
function checkRow(c){return `<label class="logistics-check ${c.done?'done':''}"><input type="checkbox" aria-label="${esc(c.title)}" data-prep="${c.id}" ${c.done?'checked':''}><span class="grow"><strong>${esc(c.title)}</strong><small>${esc(c.owner)} · ${esc(c.group)} · ${esc(c.due||'时间待定')}</small></span>${c.done?badge('已落实','green'):badge('待落实','amber')}</label>`;}
function schedule(){const e=state.events.find(e=>e.id===selectedEvent)||state.events[0];return `${head('通告与日程','正式安排、出行与准备事项放在一起，临时变化有据可查。',button(icon('download','tiny')+'导出今日通告','export-call'))}<div class="toolbar"><div class="row"><strong style="font-size:14px">2026 年 10 月 23 日 · 星期五</strong></div><div class="segmented">${[['day','今日通告'],['month','连续月程'],['list','日程列表']].map(([v,t])=>`<button data-action="calendar-view" data-id="${v}" class="${calendarView===v?'active':''}">${t}</button>`).join('')}</div></div>${calendarView==='day'?callSheet():`<div class="calendar-layout"><section class="panel"><div class="panel-head"><div class="legend"><span><i></i>项目区间</span><span><i class="sage"></i>周期发生日</span><span><i class="sand"></i>临时项目</span></div></div>${calendarView==='month'?monthMarkup(2026,10)+`<div class="calendar-scroll-note">${icon('down','tiny')} 下一月直接接续</div>`+monthMarkup(2026,11):state.events.map(e=>`<div class="schedule-list-row"><div class="agenda-time">${day(e.start)}</div><div class="grow"><strong>${esc(e.title)}</strong><small>${fmt(e.start)}–${fmt(e.end)} · ${esc(e.location)}</small></div>${badge(e.status,stateColor(e.status))}${button('调整申请','event-detail','small',`data-id="${e.id}"`)}</div>`).join('')}</section><aside class="stack">${eventPanel(e)}${note('项目长条表示项目区间，不代表全天占用。待批建议不替换正式日程。')}</aside></div>`}`;}
function eventPanel(e){return panel('正式日程',`<div class="panel-body"><h3>${esc(e.title)}</h3><dl class="detail-kv"><dt>时间</dt><dd>${dateTime(e.start)}–${fmt(e.end)}</dd><dt>地点</dt><dd>${esc(e.location)}</dd><dt>成员</dt><dd>${e.members.join('、')}</dd><dt>正式版本</dt><dd>r${e.revision} · ${e.status}</dd></dl>${button(icon('edit','tiny')+'申请调整日程','event-detail','primary',`data-id="${e.id}"`)}</div>`);}
function callSheet(){const e=state.events[0],tr=state.travel.find(t=>t.id==='tr1');return `<div class="grid-main"><div class="stack"><section class="panel"><div class="panel-head"><div><h2>今日通告单</h2><p class="panel-sub">艺人正式通告 + 团队执行准备</p></div>${badge('正式通告 r'+e.revision,'blue')}</div><div class="call-timeline">${[['准备','出发前准备','核对妆发、服装、随身物品、餐食和入场证','团队清单','checklists'],[tr?.time||'待定','集合与接送',`${tr?.meeting||'集合点待确认'} → ${tr?.destination||'目的地待定'}`,`${tr?.owner||'负责人待确认'} · ${tr?.status||'待安排'}`,'travel'],[fmt(e.start),e.title,`${e.location} · ${e.members.join('、')}`,`正式安排 · ${e.status}`,'event',e.id],...state.events.filter(x=>x.start.startsWith('2026-10-23')&&x.id!==e.id).map(x=>[fmt(x.start),x.title,`${x.location} · ${x.members.join('、')}`,`正式安排 · ${x.status}`,'event',x.id]),['收工后','物品清点与交接','服装借还、随身物品、返程确认和费用票据','赵晴 / 周言','handoff']].map(([time,t,d,s,r,eventId],i)=>`<div class="call-step"><div class="call-time">${time}</div><div class="call-dot ${i===2?'formal':''}"></div><div class="grow"><div class="row between"><h3>${esc(t)}</h3>${badge(s,i===2?'blue':'')}</div><p>${esc(d)}</p>${r==='event'?button('查看 / 申请调整','event-detail','small',`data-id="${eventId||e.id}"`):`<a class="text-btn" href="#${r}">查看执行信息 ${icon('arrow','tiny')}</a>`}</div></div>`).join('')}</div></section><section class="panel"><div class="panel-head"><h2>通告关联清单</h2><a class="text-btn" href="#checklists">管理清单</a></div><div class="panel-body" style="padding-top:4px">${state.preparations.filter(c=>c.eventId===e.id).map(checkRow).join('')}</div></section></div><aside class="stack">${eventPanel(e)}${panel('当日联系人',`<div class="panel-body">${state.contacts.filter(c=>c.eventId===e.id).slice(0,3).map(c=>`<div class="contact-mini"><div class="row between"><h3>${esc(c.name)}</h3>${badge(c.role)}</div><p>${esc(c.channel)}</p></div>`).join('')}<a class="text-btn mt" href="#site">全部现场联络 ${icon('arrow','tiny')}</a></div>`)}${panel('变更提醒',teaser())}</aside></div>`;}
function travel(){const rows=state.travel.filter(t=>travelFilter==='全部'||t.kind===travelFilter);return `${head('差旅与接送','把需求、集合地点、负责人和确认状态落实到每一段行程。',button(icon('plus','tiny')+'登记行程','new-record','primary','data-kind="travel"'))}<div class="toolbar"><div class="segmented">${['全部','车辆接送','机票 / 高铁','住宿'].map(t=>`<button data-action="travel-filter" data-id="${t}" class="${travelFilter===t?'active':''}">${t}</button>`).join('')}</div><span class="muted" style="font-size:10px">需求登记与实际预订分别确认</span></div><div class="grid-three">${rows.map(t=>`<article class="panel trip-card"><div class="row between"><span class="trip-symbol">${icon(t.kind==='住宿'?'hotel':t.kind==='机票 / 高铁'?'ticket':'car')}</span>${badge(t.status,stateColor(t.status))}</div><div><span class="muted" style="font-size:9px">${esc(t.kind)} · ${esc(t.date)}</span><h3>${esc(t.title)}</h3></div><div class="trip-route"><div><small>集合 / 出发</small><strong>${esc(t.time||'待确认')}</strong><span>${esc(t.meeting||'待确认')}</span></div>${icon('arrow')}<div><small>目的地 / 预计到达</small><strong>${esc(t.endtime||'待确认')}</strong><span>${esc(t.destination||'待确认')}</span></div></div><dl class="detail-kv"><dt>执行人</dt><dd>${esc(t.owner)}</dd><dt>司机 / 供应方</dt><dd>${esc(t.provider)}</dd><dt>车辆 / 订单</dt><dd>${esc(t.vehicle)}</dd><dt>关联通告</dt><dd>${esc(eventName(t.eventId))}</dd></dl><div class="row between">${button('查看与更新','edit-record','small',`data-kind="travel" data-id="${t.id}"`)}<span class="muted" style="font-size:9px">工作安排登记</span></div></article>`).join('')||'<div class="panel empty">此分类暂无行程，可先登记需求。</div>'}</div>`;}
function site(){return `${head('现场与联络','进场、候场、休息、现场变化，每项都找到对应联系人。',button(icon('plus','tiny')+'添加联系人','new-record','primary','data-kind="contacts"'))}<div class="grid-main"><div class="stack"><section class="panel"><div class="panel-head"><h2>项目联系人</h2><span class="muted" style="font-size:10px">仅展示虚拟演示联络信息</span></div><div class="table-scroll"><table class="asset-table"><thead><tr><th>联系人 / 职责</th><th>所属单位</th><th>联系渠道</th><th>团队对接人</th><th></th></tr></thead><tbody>${state.contacts.map(c=>`<tr><td><strong>${esc(c.name)}</strong><p class="panel-sub">${esc(c.role)}</p></td><td>${esc(c.org)}</td><td>${esc(c.channel)}</td><td>${esc(c.owner)}</td><td><button class="text-btn" data-action="edit-record" data-kind="contacts" data-id="${c.id}">查看与更新</button></td></tr>`).join('')}</tbody></table></div></section><section class="panel"><div class="panel-head"><h2>现场准备事项</h2><a class="text-btn" href="#checklists">查看清单</a></div><div class="panel-body">${state.preparations.filter(c=>['现场对接','安全与隐私'].includes(c.group)).map(checkRow).join('')}</div></section></div><aside class="stack">${panel('现场执行卡',`<div class="panel-body"><h3>《回声》片场到场</h3><dl class="detail-kv"><dt>正式地点</dt><dd>${esc(state.events[0]?.location||'暂无正式地点')}</dd><dt>接待对接</dt><dd>${esc(state.contacts[0]?.name||'待登记')}</dd><dt>统筹负责人</dt><dd>林舒</dd><dt>重点核对</dt><dd>人员名单、工作证、候场区、休息室</dd></dl><div class="annotation">如现场改变到场时段，由团队发起日程申请；获批后再协调车辆与相关人员。</div></div>`)}${panel('信息分发范围',`<div class="panel-body"><p class="muted" style="font-size:11px;line-height:1.9">通告、住址、证件和私人联系信息按职责分发。供应方只接收本次执行所需的信息。</p></div>`)}</aside></div>`;}
function checklists(){const groups=['出发前','现场对接','妆发与服装','餐食与休息','安全与隐私','收工后'],done=state.preparations.filter(c=>c.done).length;return `${head('准备清单','谁负责、什么时候核对、是否落实，每一项都能查清楚。',button(icon('plus','tiny')+'添加准备事项','new-record','primary','data-kind="preparations"'))}<div class="toolbar"><div class="filters"><select id="check-filter" aria-label="筛选准备类别">${['全部',...groups].map(g=>`<option ${checkFilter===g?'selected':''}>${g}</option>`).join('')}</select><span class="muted" style="font-size:10px">已落实 ${done} / ${state.preparations.length} 项</span></div><div style="width:180px"><div class="progress"><i style="width:${state.preparations.length?done/state.preparations.length*100:0}%"></i></div></div></div><div class="grid-two">${groups.filter(g=>checkFilter==='全部'||checkFilter===g).map((g,i)=>{const ls=state.preparations.filter(c=>c.group===g);return panel(g,`<div class="panel-body" style="padding-top:5px">${ls.map(c=>`<div class="prep-edit-row">${checkRow(c)}<button class="prep-edit" data-action="edit-record" data-kind="preparations" data-id="${c.id}" aria-label="编辑${esc(c.title)}">${icon('edit','tiny')}</button></div>`).join('')||'<div class="empty">暂无准备事项</div>'}</div>`,badge(ls.filter(c=>c.done).length+'/'+ls.length,i%2?'green':'blue'));}).join('')}</div>`;}
function handoff(){const sum=state.expenses.reduce((n,e)=>n+Number(e.amount||0),0);return `${head('费用与交接','票据、借用物和接收依据一起留存，收工后逐项收尾。',button(icon('plus','tiny')+(handoffTab==='items'?'登记物品':'登记费用'),'new-record','primary',`data-kind="${handoffTab==='items'?'belongings':'expenses'}"`))}<div class="toolbar"><div class="segmented"><button data-action="handoff-tab" data-id="items" class="${handoffTab==='items'?'active':''}">物品与交接</button><button data-action="handoff-tab" data-id="expenses" class="${handoffTab==='expenses'?'active':''}">费用与票据</button></div><span class="muted" style="font-size:10px">${handoffTab==='expenses'?'演示登记合计 ¥'+sum.toFixed(2)+' · 不产生实际支付':'登记保管人、接收人及交接依据'}</span></div><section class="panel"><div class="table-scroll"><table class="asset-table"><thead><tr>${(handoffTab==='items'?['物品 / 数量','当前保管人','交接给','归还 / 交接日期','状态','']:['费用项目','类别 / 经办人','登记金额','票据','核对状态','']).map(t=>`<th>${t}</th>`).join('')}</tr></thead><tbody>${(handoffTab==='items'?state.belongings:state.expenses).map(r=>handoffTab==='items'?`<tr><td><strong>${esc(r.title)}</strong><p class="panel-sub">${esc(r.qty)} · ${esc(eventName(r.eventId))}</p></td><td>${esc(r.holder)}</td><td>${esc(r.recipient)}</td><td>${esc(r.due)}</td><td>${badge(r.status,stateColor(r.status))}</td><td><button class="text-btn" data-action="edit-record" data-kind="belongings" data-id="${r.id}">交接记录</button></td></tr>`:`<tr><td><strong>${esc(r.title)}</strong><p class="panel-sub">${esc(eventName(r.eventId))}</p></td><td>${esc(r.category)} · ${esc(r.owner)}</td><td>¥${Number(r.amount).toFixed(2)}</td><td>${badge(r.receipt,r.receipt==='待补票据'?'amber':'green')}</td><td>${badge(r.status,stateColor(r.status))}</td><td><button class="text-btn" data-action="edit-record" data-kind="expenses" data-id="${r.id}">核对记录</button></td></tr>`).join('')}</tbody></table></div></section><div class="grid-two mt">${panel('收工检查',`<div class="panel-body">${state.preparations.filter(c=>c.group==='收工后').map(checkRow).join('')}</div>`)}${panel('交接记录要求',`<div class="panel-body"><ul class="info-list"><li>物品：数量、保管人、交给谁、何时归还。</li><li>接收或归还须填写确认依据，不能仅凭状态判断。</li><li>费用：经办人、用途、金额、票据与核对进度。</li><li>登记不等于实际报销或付款。</li></ul></div>`)}</div>`;}
function reviews(){return `${head('变更申请','团队提出日程调整，艺人批准后再同步执行。')}<div class="toolbar"><span class="muted" style="font-size:11px">全部申请 ${state.requests.length} 项 · 待批准 ${countPending()} 项</span>${badge('A / B 共享正式版本','blue')}</div><section class="panel">${state.requests.map(r=>`<div class="request-row"><div class="request-type">${icon('calendar')}</div><div class="grow"><div class="row between"><h3>${esc(r.before.title)}</h3>${badge(r.status,stateColor(r.status))}</div><p>林舒发起 · 仅本次 · 基于 r${r.base_revision}</p><div class="row mt wrap" style="margin-top:12px;font-size:11px;color:#919bb4"><del>${dateTime(r.before.start)}–${fmt(r.before.end)}</del>${icon('arrow','tiny')}<span style="color:#7182c1">${dateTime(r.after.start)}–${fmt(r.after.end)}</span>${r.conflicts.length?badge('⚠ 时间冲突','red'):''}</div></div>${button('查看差异','request-detail','small',`data-id="${r.id}"`)}</div>`).join('')||'<div class="empty">暂无变更申请</div>'}</section>${state.syncs.length?panel('接收到的艺人端更新',`<div class="panel-body">${state.syncs.map(s=>`<div class="sync-entry"><div class="row between"><h3>${esc(s.after.title)}</h3>${badge(s.status,'green')}</div><p>正式版本 r${s.after.revision} · 相关旧申请不再可覆盖</p><button class="text-btn" data-action="sync-detail" data-id="${s.id}">查看前后差异</button></div>`).join('')}</div>`):''}<p class="muted mt" style="font-size:10px">理由、讨论标注与审批意见分别保留。批准前正式值不变，发生冲突时明确标红。</p>`;}
function team(){return `<div id="live-account-list"></div>${head('团队与权限','按后勤职责分工，成员只接触自己负责的项目和执行信息。')}<div class="grid-three">${[['林舒','舒','后勤统筹','通告、人员协调、准备事项'],['周言','言','差旅协调','车辆、交通、住宿与票据'],['赵晴','晴','现场执行','妆发服装对接、物品借还']].map(([n,a,r,d])=>`<section class="panel panel-body"><div class="row mb"><span class="avatar">${a}</span><div><h3>${n}</h3><p class="panel-sub">演示成员</p></div></div>${badge(r,'blue')}<p class="muted mt" style="font-size:11px">${d}</p></section>`).join('')}</div><section class="panel mt"><div class="panel-head"><h2>后勤工作权限</h2><span class="muted" style="font-size:10px">按项目及资源范围授予</span></div><div class="table-scroll"><table class="permissions"><thead><tr><th>事项</th><th>后勤统筹</th><th>差旅协调</th><th>现场执行</th><th>管理员</th></tr></thead><tbody>${[['通告查看','授权项目','负责行程','负责现场','需加入项目'],['正式日程调整','提交申请','提交申请','提交申请','提交申请'],['差旅与联系人','职责内','职责内','职责内','单独授权'],['准备事项与物品','职责内','职责内','职责内','单独授权'],['费用与票据','单独授权','经办范围','经办范围','单独授权'],['私密个人记录','无默认权限','无默认权限','无默认权限','无默认权限']].map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div></section><div class="grid-two mt">${panel('信息分发',`<div class="panel-body"><p class="muted" style="font-size:11px;line-height:1.9">司机接收集合点、时间与必要联络信息；现场人员接收现场要求；住宿信息仅给负责人员。私人笔记、练习和个人发展内容不进入后勤工作台。</p></div>`)}${panel('日程权限',`<div class="panel-body"><p class="muted" style="font-size:11px;line-height:1.9">团队任何角色调整正式日程都先申请。艺人端修改直接同步，团队据此更新接送、准备与现场协调。</p></div>`)}</div>`;}
const recordFields={
 travel:[['title','行程名称'],['kind','行程类型',['车辆接送','机票 / 高铁','住宿']],['date','日期','date'],['time','集合 / 出发时间','time'],['endtime','预计到达时间','time'],['meeting','集合点 / 出发地'],['destination','目的地 / 住宿位置'],['provider','司机 / 供应方'],['vehicle','车辆 / 班次 / 需求登记'],['owner','负责人'],['status','落实状态',['待安排','待确认','已确认','已到位','已完成']],['eventId','关联通告','events'],['note','执行备注','textarea']],
 contacts:[['name','联系人姓名'],['role','负责事项'],['org','所属单位'],['channel','联系渠道'],['location','对接地点'],['owner','团队对接人'],['eventId','关联通告','events'],['note','现场要求与备注','textarea']],
 preparations:[['title','准备事项'],['group','准备类别',['出发前','现场对接','妆发与服装','餐食与休息','安全与隐私','收工后']],['owner','负责人'],['due','检查时间','time'],['eventId','关联通告','events']],
 expenses:[['title','费用项目'],['category','费用类别',['交通','住宿','餐食','物品','其他']],['amount','登记金额（元）','number'],['owner','经办人'],['receipt','票据状态',['待补票据','已登记票据','无需票据说明']],['status','核对状态',['待核对','已核对','已提交财务']],['eventId','关联通告','events'],['note','用途与核对备注','textarea']],
 belongings:[['title','物品名称'],['qty','数量'],['holder','当前保管人'],['recipient','交接给'],['due','计划交接 / 归还日期','date'],['status','交接状态',['待交接','待接收','已接收','待归还','已归还']],['evidence','接收 / 归还确认依据'],['eventId','关联通告','events'],['note','清点与交接备注','textarea']]
};
const kindNames={travel:'行程',contacts:'联系人',preparations:'准备事项',expenses:'费用',belongings:'物品交接'};
function recordModal(kind,id){const r=id?state[kind].find(x=>x.id===id):null;modal((r?'更新':'登记')+kindNames[kind],kind==='travel'?'记录执行信息；涉及正式通告变化时仍需发起日程申请。':kind==='expenses'?'费用登记与实际报销、支付分别处理。':kind==='belongings'?'填写保管人、接收人、数量与确认依据。':'按实际分工落实到人。',`<form id="record-form"><input type="hidden" name="_collection" value="${kind}"><input type="hidden" name="id" value="${r?.id||''}"><div class="form-grid">${recordFields[kind].map(([key,label,type],idx)=>{const value=r?.[key]??(key==='owner'?'林舒':key==='date'?'2026-10-23':''),required=idx===0||['owner','holder','recipient','qty','amount'].includes(key);let input=Array.isArray(type)?`<select name="${key}">${type.map(t=>`<option ${value===t?'selected':''}>${t}</option>`).join('')}</select>`:type==='events'?`<select name="${key}">${state.events.map(e=>`<option value="${e.id}" ${value===e.id?'selected':''}>${esc(e.title)}</option>`).join('')}</select>`:type==='textarea'?`<textarea name="${key}">${esc(value)}</textarea>`:`<input name="${key}" type="${type||'text'}" value="${esc(value)}" ${required?'required':''} ${type==='number'?'min="0" step="0.01"':''} maxlength="180">`;return `<label class="field ${type==='textarea'?'full':''}"><span>${label}${required?' *':''}</span>${input}</label>`;}).join('')}</div><div class="form-error" id="form-error"></div></form>`,button('取消','close')+button('保存登记','save-record','primary'));}
async function saveRecord(){const f=document.querySelector('#record-form');if(!f.reportValidity())return;const values=Object.fromEntries(new FormData(f)),{_collection:kind,id,...v}=values;if(kind==='expenses')v.amount=Number(v.amount);if(kind==='belongings'&&['已接收','已归还'].includes(v.status)&&!v.evidence.trim()){document.querySelector('#form-error').textContent='标记已接收或已归还时，请填写确认依据';return;}if(id)Object.assign(state[kind].find(x=>x.id===id),v);else state[kind].unshift({...v,id:W.uid(),...(kind==='preparations'?{done:false}:{})});await audit('林舒更新了'+kindNames[kind],(v.title||v.name)+' · 本地演示登记');close();render();toast('登记已保存');}
function prototypeInfo(){drawer('本机工作台说明','双端连接版 4.0',`<p class="muted" style="font-size:11px;line-height:1.9">账号、执行记录和文字图片留痕保存于本机。项目及执行事项可留痕；仅提交本人、管理员和明星可编辑，修改保留历史。A端已使用同一服务读取和审批日程；预订、支付及外部消息未接入。</p><div class="row mt"><button class="btn" data-local-action="account">账号与退出</button><button class="btn" data-action="export-handoff">导出团队登记快照</button></div>`,button('关闭','close'));}
async function persist(){
 if(isSaving)throw Error('正在保存，请稍候。');
 isSaving=true;document.body.classList.add('is-saving');
 try{const result=await LocalApp.save(clone(state),workspaceRevision);acceptServer(result);}
 catch(error){localStorage.setItem('actorstudio-unsaved-'+currentUser.id,JSON.stringify(state));
 const fresh=await LocalApp.boot();acceptServer(fresh);render();throw error;}
 finally{isSaving=false;document.body.classList.remove('is-saving');}
}
function toast(t){const el=document.querySelector('#toast');el.textContent=t;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3500);}
async function audit(title,detail){state.audit.unshift({title,detail,time:new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit',timeZone:'Asia/Shanghai'})});state.audit=state.audit.slice(0,30);await persist();}
function go(r){route=r;close();if(location.hash!=='#'+r)history.pushState(null,'','#'+r);render();window.scrollTo(0,0);}
function countPending(){return state.requests.filter(r=>r.status==='待审批').length;}
function projectRows(){return state.projects.slice(0,4).map(p=>{const done=p.tasks.filter(t=>t.done).length,n=p.tasks.length;return `<div class="project-row"><div class="row"><div class="project-symbol ${p.color}">${icon(p.type==='recurring'?'refresh':'folder','tiny')}</div><div class="grow"><div class="name">${esc(p.name)}</div><div class="project-meta">${typeLabel(p.type)} · ${p.end?'至 '+p.end.replaceAll('-','.'):'持续进行'} </div></div></div><div>${badge(p.status,stateColor(p.status))}</div><div class="project-progress"><div class="row between progress-label"><span>任务进度</span><span>${n?done+'/'+n:'暂无任务'}</span></div>${n?`<div class="progress"><i style="width:${done/n*100}%"></i></div>`:''}</div><div class="members">${p.members.map((m,i)=>`<span class="avatar ${i%2?'green':''}">${m}</span>`).join('')}</div><button data-action="project-detail" data-id="${p.id}" aria-label="查看${esc(p.name)}">${icon('chevron','tiny')}</button></div>`;}).join('');}
function agenda(){return state.events.filter(e=>e.status!=='已取消'&&e.start.startsWith('2026-10-23')).slice(0,3).map((e,i)=>`<button class="agenda-row" style="text-align:left;width:100%" data-action="event-detail" data-id="${e.id}"><div class="agenda-time">${fmt(e.start)}<br><span style="font-size:8px;color:#b6bdcd">${day(e.start)}</span></div><div class="agenda-line ${['','amber','green'][i]}"><h3>${esc(e.title)}</h3><p>${esc(e.location)} · ${e.members.slice(0,2).join('、')}</p></div></button>`).join('');}
function teaser(){const r=state.requests.find(r=>r.status==='待审批');return r?`<div class="review-teaser"><div class="row between">${badge('日程调整','blue')}${badge('等待明星批准','amber')}</div><h3>${esc(r.before.title)}</h3><div class="mini-diff"><del>${fmt(r.before.start)}–${fmt(r.before.end)}</del>${icon('arrow','tiny')}<strong>${fmt(r.after.start)}–${fmt(r.after.end)}</strong></div>${r.conflicts.length?`<div style="font-size:9px;color:var(--red);margin-bottom:12px">${icon('warn','tiny')} 时间冲突 · ${r.conflicts[0].minutes} 分钟重叠</div>`:''}<button class="text-btn" data-action="request-detail" data-id="${r.id}">查看前后差异 ${icon('arrow','tiny')}</button></div>`:`<div class="empty">${icon('check')}<p>暂无待审批申请</p></div>`;}
function projects(){let list=state.projects.filter(p=>projectFilter==='全部'||typeLabel(p.type)===projectFilter);return `${head('项目与任务','把长期拍摄、周期保障和临时活动落实到团队任务。',button(icon('plus','tiny')+'新建项目','new-project','primary'))}<div class="toolbar"><div class="segmented">${['全部','长期项目','周期项目','临时项目'].map(t=>`<button data-action="project-filter" data-id="${t}" class="${projectFilter===t?'active':''}">${t}</button>`).join('')}</div><div class="segmented"><button data-action="project-view" data-id="cards" class="${projectView==='cards'?'active':''}">项目卡片</button><button data-action="project-view" data-id="board" class="${projectView==='board'?'active':''}">任务看板</button></div></div>${projectView==='board'?taskBoard(list):`<div class="grid-three">${list.map(p=>{const n=p.tasks.length,done=p.tasks.filter(t=>t.done).length;return `<article class="panel project-card"><div class="row between"><span class="project-symbol ${p.color}">${icon(p.type==='recurring'?'refresh':'folder')}</span>${badge(typeLabel(p.type),'blue')}</div><div><h3>${esc(p.name)}</h3><p>${esc(p.description)}</p></div><div class="stat-pair"><div><small>负责人</small><strong>${esc(p.owner)}</strong></div><div><small>项目状态</small><strong>${esc(p.status)}</strong></div></div><div><div class="row between progress-label"><span>已完成任务</span><span>${n?done+' / '+n:'暂无任务'}</span></div>${n?`<div class="progress"><i style="width:${done/n*100}%"></i></div>`:`<p style="font-size:9px;margin-top:6px">添加任务后显示实际进度</p>`}</div><div class="project-card-footer"><div class="members">${p.members.map(m=>`<span class="avatar">${m}</span>`).join('')}</div><span>${p.type==='recurring'?esc(p.rule||'周期待设置'):p.end?'至 '+p.end:'未设置结束日期'}</span></div>${button('进入项目 '+icon('arrow','tiny'),'project-detail','','data-id="'+p.id+'"')}</article>`;}).join('')}</div>`}${note('新建项目和分配任务不会自动确认正式日程。B 端日程变更须先提交申请。')}`;}
function taskBoard(list){return `<div class="kanban">${[['待确认',false],['进行中',false],['已完成',true]].map(([name,done],ci)=>`<div class="kanban-col"><h3>${name}</h3>${list.flatMap(p=>p.tasks.map((t,i)=>({...t,p,i}))).filter(t=>done?t.done:!t.done&&(ci===0?!t.acceptedAt:!!t.acceptedAt)).map(t=>`<article class="task-card"><h3>${esc(t.title)}</h3><p>${esc(t.p.name)}</p><div class="row between">${badge(t.status||(t.done?'已完成':'待办'),t.done?'green':'blue')}<button class="text-btn" data-action="project-detail" data-id="${t.p.id}">查看任务</button></div></article>`).join('')||'<div class="empty" style="padding:20px">当前没有任务</div>'}</div>`).join('')}</div>`;}
function projectModal(id){const p=id?project(id):null;modal(p?'项目详情':'新建团队项目',p?`${typeLabel(p.type)} · ${p.name}`:'先选择项目类型，再组织时间与分工。',`<form id="project-form"><input type="hidden" name="id" value="${p?.id||''}"><div class="form-grid"><label class="field full"><span>项目名称</span><input name="name" maxlength="60" required value="${esc(p?.name||'')}" placeholder="例如：《回声》拍摄后勤"></label><label class="field"><span>项目类型</span><select name="type" id="project-type">${['long_term','recurring','temporary'].map(t=>`<option value="${t}" ${p?.type===t?'selected':''}>${typeLabel(t)}</option>`).join('')}</select></label><label class="field"><span>负责人</span><select name="owner">${['林舒','赵晴','周言'].map(n=>`<option ${p?.owner===n?'selected':''}>${n}</option>`).join('')}</select></label><label class="field"><span>开始日期（可选）</span><input type="date" name="start" value="${p?.start||''}"></label><label class="field"><span>结束日期（可选）</span><input type="date" name="end" value="${p?.end||''}"></label><label class="field full" id="rule-field" ${p?.type!=='recurring'?'hidden':''}><span>重复规则（项目计划，不生成正式预约）</span><select name="rule">${['每周一、周四','每周三','每周五','每月第一个周一'].map(t=>`<option ${p?.rule===t?'selected':''}>${t}</option>`).join('')}</select><small>发生次与日程提交，在后续双端接口中统一展开。</small></label><label class="field"><span>项目状态</span><select name="status">${['草稿','进行中','已暂停','已完成','已归档'].map(x=>`<option ${p?.status===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="field full"><span>项目说明</span><textarea name="description">${esc(p?.description||'')}</textarea></label></div><div class="form-error" id="form-error"></div></form>${p?`<hr class="rule-divider"><div class="row between mb"><h3>项目任务</h3><button class="text-btn" data-action="add-task" data-id="${p.id}">${icon('plus','tiny')}添加任务</button></div>${p.tasks.map(t=>`<label class="task-check ${t.done?'done':''}"><input type="checkbox" data-task="${t.id}" data-project="${p.id}" ${t.done?'checked':''}><span>${esc(t.title)}${t.origin==='artist'?`<em class="ab-task-meta">A端发布 · ${esc(t.assigneeName)}${t.due?' · 截止 '+new Date(t.due).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}):''}${t.note?'<br>'+esc(t.note):''}</em>`:''}</span><small>${t.origin==='artist'?esc(t.status):t.done?'已完成':'待办'}</small></label>`).join('')||'<p class="muted" style="font-size:10px">尚无任务，不显示完成百分比。</p>'}`:''}`,button('取消','close')+button('保存项目','save-project','primary'));}
function addTask(id){modal('添加任务','任务归属与日程预约分别管理。',`<form id="task-form"><input type="hidden" name="project" value="${id}"><label class="field"><span>任务标题</span><input name="title" required maxlength="80"></label><p class="muted" style="font-size:10px">团队内部项目待办；艺人发布的任务由指定负责人接受。</p></form>`,button('取消','close')+button('添加任务','save-task','primary'));}
function monthMarkup(y,m){const first=new Date(Date.UTC(y,m-1,1)),weekday=(first.getUTCDay()+6)%7,start=new Date(Date.UTC(y,m-1,1-weekday));const days=new Date(Date.UTC(y,m,0)).getUTCDate(),weeks=Math.ceil((weekday+days)/7);let out=`<div class="month-wrap"><div class="month-heading"><strong>${y} 年 ${m} 月</strong><span>${m===10?'OCTOBER':'NOVEMBER'}</span></div><div class="weekdays">${['周一','周二','周三','周四','周五','周六','周日'].map(d=>`<span>${d}</span>`).join('')}</div>`;
 const bars=state.projects.filter(p=>p.start&&p.end&&p.status!=='已归档').map(p=>({start:p.start,end:p.end,title:p.name,id:p.id,color:p.color,action:'project-detail',lane:p.type==='temporary'?2:1}));
 state.events.forEach(e=>{if(e.status!=='已取消')bars.push({start:e.start.slice(0,10),end:e.start.slice(0,10),title:fmt(e.start)+' '+e.title,id:e.id,color:project(e.projectId)?.color||'blue',action:'event-detail',lane:e.id==='e4'?3:e.id==='e2'?5:4});});
 for(let w=(m>10&&weekday>0?1:0);w<weeks;w++){const ws=new Date(start.getTime()+w*7*86400000).toISOString().slice(0,10),we=new Date(start.getTime()+(w*7+6)*86400000).toISOString().slice(0,10);out+='<div class="week">';for(let d=0;d<7;d++){let dt=new Date(start.getTime()+(w*7+d)*86400000),iso=dt.toISOString().slice(0,10);out+=`<div class="day ${dt.getUTCMonth()!==m-1?'other':''}" style="grid-column:${d+1}"><span class="${iso==='2026-10-23'?'today':''}">${dt.getUTCDate()}</span></div>`;}
 const recurring=project('p2');if(recurring&&recurring.status!=='已归档'){for(let d=0;d<7;d++){const date=new Date(start.getTime()+(w*7+d)*86400000).toISOString().slice(0,10);if([0,3].includes(d)&&date>='2026-10-22')out+=`<button class="cal-bar sage" style="grid-column:${d+1};grid-row:4" data-action="project-detail" data-id="p2">训练保障</button>`;}}
 bars.filter(b=>b.start<=we&&b.end>=ws).forEach(b=>{const a=Math.max(0,Math.round((Date.parse(b.start)-Date.parse(ws))/86400000)),z=Math.min(6,Math.round((Date.parse(b.end)-Date.parse(ws))/86400000));out+=`<button class="cal-bar ${b.color}" style="grid-column:${a+1}/span ${z-a+1};grid-row:${b.lane+1}" data-action="${b.action}" data-id="${b.id}" title="${esc(b.title)}">${b.start<ws?'‹ ':''}${esc(b.title)}${b.end>we?' ›':''}</button>`;});out+='</div>';
 }return out+'</div>';}
function eventModal(id){const e=state.events.find(e=>e.id===id);selectedEvent=id;drawer('发起日程调整申请','B 端提出建议，A 端批准前正式日程保持原样。',`<div class="row between mb"><h3>${esc(e.title)}</h3>${badge('正式版本 r'+e.revision,'blue')}</div><div class="selected-day">原安排：${dateTime(e.start)}–${fmt(e.end)} · ${esc(e.location)}</div><form id="schedule-form"><input type="hidden" name="id" value="${id}"><input type="hidden" name="base" value="${e.revision}"><input type="hidden" name="key" value="${W.uid()}"><div class="form-grid"><label class="field full"><span>调整日期</span><input type="date" name="date" value="${e.start.slice(0,10)}" required></label><label class="field"><span>开始时间</span><input type="time" name="start" value="${fmt(e.start)}" required></label><label class="field"><span>结束时间</span><input type="time" name="end" value="${fmt(e.end)}" required></label><label class="field full"><span>地点</span><input name="location" value="${esc(e.location)}"></label>${e.series_id?`<label class="field full"><span>周期作用范围</span><select name="scope"><option value="occurrence">仅本次</option><option disabled>本次及以后 · 待双端周期接口</option><option disabled>全系列 · 待双端周期接口</option></select><small>当前支持单次正式安排变更；系列重展开留待正式实现验收。</small></label>`:''}<label class="field full"><span>发起理由 *</span><textarea name="reason" placeholder="说明这次调整的原因" required></textarea></label><label class="field full"><span>修改标注（可选）</span><textarea name="note" placeholder="例如：请保留 30 分钟准备时间"></textarea></label></div><div class="form-error" id="form-error"></div><div id="edit-conflicts"></div></form>${note('当前权限：项目负责人。管理员、负责人均通过申请调整日程。')}`,button('取消','close')+button('预览修改差异','preview-request','primary'));updateEditConflicts();}
function proposalFromForm(form){const fd=new FormData(form),v=Object.fromEntries(fd);return {v,proposal:{start:v.date+'T'+v.start+':00+08:00',end:v.date+'T'+v.end+':00+08:00',location:v.location}};}
function updateEditConflicts(){const form=document.querySelector('#schedule-form');if(!form)return;const {v,proposal}=proposalFromForm(form),e=state.events.find(e=>e.id===v.id),cs=W.conflicts(state.events,{...e,...proposal},e.id);document.querySelector('#edit-conflicts').innerHTML=conflictBox(cs);}
function conflictBox(cs){return cs.length?`<div class="danger-box">${icon('warn')}<div><strong>时间冲突 · ${cs.length} 项</strong>${cs.map(c=>`${esc(c.title)} · ${fmt(c.start)}–${fmt(c.end)}<br>${esc(c.members.join('、'))} · 重叠 ${c.minutes} 分钟`).join('<br>')}<br>是否保留冲突，由 A 端决定。</div></div>`:`<div class="notice" style="margin:0">${icon('check')}<span>当前有权查看的团队日程中，未发现时间冲突。私人日程未参与检查。</span></div>`;}
let pendingForm=null;
function previewRequest(){const form=document.querySelector('#schedule-form');if(!form.reportValidity())return;const {v,proposal}=proposalFromForm(form),e=state.events.find(e=>e.id===v.id);if(Date.parse(proposal.end)<=Date.parse(proposal.start)){document.querySelector('#form-error').textContent='结束时间必须晚于开始时间';return;}if(e.revision!==Number(v.base)){document.querySelector('#form-error').textContent='正式版本已更新，请关闭后重新发起申请';return;}pendingForm={v,proposal};drawer('确认日程调整','修改前后对比 · 提交后只写入申请',comparison(e,{...e,...proposal})+conflictBox(W.conflicts(state.events,{...e,...proposal},e.id))+`<hr class="rule-divider"><div class="list-title">发起理由</div><p style="font-size:11px;color:#8892ae">${esc(v.reason)}</p>${v.note?`<div class="annotation">修改标注：${esc(v.note)}</div>`:''}`,button('返回编辑','back-edit')+button('提交给 A 端','submit-request','primary'));}
function comparison(before,after,afterLabel){const fields=[['日期',day(before.start),day(after.start)],['开始 / 结束',fmt(before.start)+'–'+fmt(before.end),fmt(after.start)+'–'+fmt(after.end)],['地点',before.location,after.location],['成员',before.members.join('、'),after.members.join('、')]].filter(x=>x[1]!==x[2]);const bh=Number(fmt(before.start).slice(0,2))+Number(fmt(before.start).slice(3))/60,ah=Number(fmt(after.start).slice(0,2))+Number(fmt(after.start).slice(3))/60,min=Math.floor(Math.min(bh,ah))-1;
 const bar=(e)=>{const a=(Date.parse(e.start)-Date.parse(e.start.slice(0,10)+'T00:00:00+08:00'))/3600000,z=(Date.parse(e.end)-Date.parse(e.start))/3600000;return `grid-column:${Math.max(1,Math.min(9,Math.floor(a-min)+1))}/span ${Math.max(1,Math.min(4,Math.ceil(z)))}`;};
 return `<div class="comparison"><div class="compare-card"><small>修改前 · 正式 r${before.revision}</small><strong>${fmt(before.start)}–${fmt(before.end)}</strong><p>${day(before.start)} · ${esc(before.location)}</p></div><div class="compare-card after"><small>修改后 · ${afterLabel||(after.revision===before.revision?'提议':'正式 r'+after.revision)}</small><strong>${fmt(after.start)}–${fmt(after.end)}</strong><p>${day(after.start)} · ${esc(after.location)}</p></div></div><div class="compare-timeline">${Array.from({length:10},(_,i)=>`<small>${min+i}:00</small>`).join('')}<div class="compare-range" style="${bar(before)}">原时段</div><div class="compare-range new" style="${bar(after)}">新时段</div></div><table class="diff-table"><thead><tr><th>修改字段</th><th>原值</th><th>新值</th></tr></thead><tbody>${fields.map(([f,a,b])=>`<tr><td>${f}</td><td>${esc(a)}</td><td>${esc(b)}</td></tr>`).join('')||'<tr><td colspan="3">无字段差异</td></tr>'}</tbody></table><p class="muted" style="font-size:9px;margin:10px 0 19px">未修改字段已收起 · 时区 Asia/Shanghai · ${Math.round((Date.parse(after.end)-Date.parse(after.start))/60000)} 分钟</p>`;}
function requestDetail(id){const r=state.requests.find(r=>r.id===id);drawer('日程调整申请','固定修改前后快照 · 正式值与提议分别保留',`<div class="row between mb"><h3>${esc(r.before.title)}</h3>${badge(r.status,stateColor(r.status))}</div>${r.status==='待更新'?note('正式版本已改变，本申请不可覆盖最新日程。请根据当前版本重新发起。',true):''}${comparison(r.before,r.after,r.status==='已批准生效'?'已生效 · 正式 r'+(r.applied_revision||r.base_revision+1):undefined)}${conflictBox(r.conflicts)}<hr class="rule-divider"><div class="row gap8 mb"><span class="avatar" style="width:25px;height:25px;font-size:9px">舒</span><div><h3 style="font-size:10px">林舒 · 发起理由</h3><small class="muted">申请基于 r${r.base_revision}</small></div></div><p style="font-size:11px;color:#8892a9">${esc(r.reason)}</p>${r.note?`<div class="annotation">修改标注：${esc(r.note)}</div>`:''}<hr class="rule-divider"><h3>讨论标注</h3>${r.comments.map(c=>`<div class="comment"><small>${esc(c.by)} · ${esc(c.at)}</small><p>${esc(c.text)}</p></div>`).join('')||'<p style="font-size:10px;color:#a8b0c2;margin:10px 0">暂无讨论，标注不会修改正式日程。</p>'}<label class="field mt"><span>添加讨论</span><textarea id="request-comment" placeholder="对时间、地点或准备工作添加说明"></textarea></label>${button('添加标注','request-comment','small',`data-id="${r.id}"`)}${r.decision?`<hr class="rule-divider"><h3>审核意见</h3><p class="muted" style="font-size:11px;margin-top:9px">${esc(r.decision.reason)}</p>`:''}${r.status==='待审批'&&currentUser.role==='artist'?`<details open class="preview-cta"><summary>明星账号审批</summary><h3 style="margin-top:12px">审核当前日程申请</h3><p>当前审批与 A 端读取同一份正式日程。</p><label class="check-label"><input type="checkbox" id="keep-conflict">明确保留上述冲突</label><label class="field"><span>审核意见 / 保留冲突原因</span><input id="decision-reason" placeholder="例如：造型沟通由团队先开始"></label><div class="form-error" id="form-error"></div><div class="row">${button('驳回申请','mock-reject','small',`data-id="${r.id}"`)}${button('批准并生效','mock-approve','small',`data-id="${r.id}"`)}</div></details>`:''}`,button('关闭','close')+(r.status==='待审批'?button('撤回申请','withdraw','danger',`data-id="${r.id}"`):r.status==='待更新'?button('基于最新版重新申请','reapply','primary',`data-id="${r.eventId}"`):''));}
function drawer(title,sub,body,footer=''){document.querySelector('#overlay').innerHTML=`<div class="drawer-backdrop"><section class="drawer" role="dialog" aria-modal="true" aria-label="${esc(title)}"><header class="drawer-head"><div><h2>${title}</h2><p>${sub}</p></div><button class="icon-button" data-action="close" aria-label="关闭">${icon('close','tiny')}</button></header><div class="drawer-body">${body}</div><footer class="drawer-footer">${footer}</footer></section></div>`;document.body.style.overflow='hidden';LocalApp.decorate();setTimeout(()=>document.querySelector('.drawer-head button')?.focus(),0);}
function modal(title,sub,body,footer=''){drawer(title,sub,body,footer);const parent=document.querySelector('.drawer-backdrop'),child=document.querySelector('.drawer');parent.className='modal-backdrop';child.className='modal';}
function close(){document.querySelector('#overlay').innerHTML='';document.body.style.overflow='';}
function download(name,contents,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([contents],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),5000);}
async function receiveMock(id,approved){await LocalApp.decision(id,approved);}
document.addEventListener('click',async ev=>{const b=ev.target.closest('[data-action]');if(!b){const link=ev.target.closest('a[href^="#"]');if(link){ev.preventDefault();go(link.getAttribute('href').slice(1));}return;}if(b.tagName==='A')ev.preventDefault();const a=b.dataset.action,id=b.dataset.id;try{switch(a){
case 'mobile-nav':document.querySelector('#sidebar').classList.toggle('open');break;
case 'route':go(id);break;case 'go-projects':go('projects');break;
case 'new-project':projectModal();break;case 'project-detail':projectModal(id);break;
case 'project-filter':projectFilter=id;render();break;case 'project-view':projectView=id;render();break;
case 'save-project':{const f=document.querySelector('#project-form');if(!f.reportValidity())break;const v=Object.fromEntries(new FormData(f));if(v.end&&v.start&&v.end<v.start){document.querySelector('#form-error').textContent='结束日期不能早于开始日期';break;}if(v.id)Object.assign(project(v.id),v);else state.projects.unshift({...v,id:W.uid(),tasks:[],members:['舒'],color:'blue'});await audit('林舒'+(v.id?'更新':'创建')+'了后勤项目',v.name+' · 不自动确认日程');close();render();toast('后勤项目已保存');break;}
case 'add-task':addTask(id);break;case 'save-task':{const f=document.querySelector('#task-form');if(!f.reportValidity())break;const v=Object.fromEntries(new FormData(f));project(v.project).tasks.push({id:W.uid(),title:v.title,done:false});await persist();projectModal(v.project);render();toast('任务已添加');break;}
case 'calendar-view':calendarView=id;render();break;case 'event-detail':eventModal(id);break;case 'preview-request':previewRequest();break;
case 'back-edit':{const p=pendingForm;eventModal(p.v.id);const f=document.querySelector('#schedule-form');Object.entries(p.v).forEach(([k,v])=>{if(f.elements[k])f.elements[k].value=v;});updateEditConflicts();break;}
case 'submit-request':{const {v,proposal}=pendingForm,r=W.submit(state,v.id,proposal,v.reason,v.note,v.key);pendingForm=null;await audit('林舒提交了日程调整申请',r.before.title+' · 正式日程未改变');close();render();requestDetail(r.id);toast('申请已保存，正式日程保持原样');break;}
case 'request-detail':requestDetail(id);break;case 'withdraw':W.withdraw(state,id);await audit('林舒撤回了申请','正式日程保持原样');close();render();toast('申请已撤回');break;
case 'reapply':eventModal(id);break;case 'request-comment':{const text=document.querySelector('#request-comment').value.trim();if(!text){toast('请先填写讨论内容');break;}state.requests.find(r=>r.id===id).comments.push({by:currentUser.display_name,text,at:new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit',timeZone:'Asia/Shanghai'})});await persist();requestDetail(id);toast('已添加讨论标注');break;}
case 'mock-approve':await receiveMock(id,true);break;case 'mock-reject':await receiveMock(id,false);break;
case 'simulate-sync':{const e=state.events[0],date=e.start.slice(0,10),s=fmt(e.start)==='13:00'?'14:00':'13:00',z=s==='13:00'?'14:00':'15:00';W.directSync(state,e.id,{start:date+'T'+s+':00+08:00',end:date+'T'+z+':00+08:00'});await audit('收到艺人端模拟更新','正式演示日程已更新，相关旧申请转待更新');close();go('reviews');toast('模拟同步完成，请按新安排核对后勤执行');break;}
case 'sync-detail':{const s=state.syncs.find(s=>s.id===id);drawer('艺人端更新详情','无需 B 端批准或已读。',comparison(s.before,s.after)+note('A端修改已生效，无需等待团队已读。请复核受影响准备。')+`<h3>受影响事项</h3><p class="muted">${(s.affected||[]).map(x=>esc(x.title)).join('、')||'暂无关联准备'}</p>${currentUser.role!=='artist'?`<button class="btn primary" data-local-action="ack-update" data-id="${s.id}">确认已知悉此版本</button>`:''}`,button('关闭','close'));break;}
case 'travel-filter':travelFilter=id;render();break;case 'handoff-tab':handoffTab=id;render();break;
case 'new-record':recordModal(b.dataset.kind);break;case 'edit-record':recordModal(b.dataset.kind,id);break;case 'save-record':await saveRecord();break;
case 'notifications':drawer('团队动态','当前账号收到的正式版本更新。',state.syncs.map(s=>`<div class="comment"><h3>${esc(s.after.title)}</h3><p>r${s.after.revision} · ${esc(s.status)}</p><button class="text-btn" data-action="sync-detail" data-id="${s.id}">查看差异与回执</button></div>`).join('')+state.audit.map(x=>`<div class="comment"><small>${esc(x.time)}</small><h3 style="margin-top:6px;font-size:11px">${esc(x.title)}</h3><p>${esc(x.detail)}</p></div>`).join(''),button('关闭','close'));break;
case 'prototype-info':prototypeInfo();break;
case 'export-call':{const lines=['ActorStudio · 今日通告（演示）','2026-10-23 · Asia/Shanghai','','正式安排',...state.events.filter(e=>e.start.startsWith('2026-10-23')).map(e=>`${fmt(e.start)}–${fmt(e.end)} ${e.title} / ${e.location} / 正式 r${e.revision}`),'','出行登记',...state.travel.filter(t=>t.date==='2026-10-23').map(t=>`${t.time||'待定'} ${t.title} / ${t.owner} / ${t.status}`),'','准备清单',...state.preparations.map(c=>`${c.done?'已落实':'待落实'} ${c.title} / ${c.owner} / ${c.due}`),'','本机共享数据快照；示例内容已标注。未连接订票、外部推送或支付。'];download('今日通告_2026-10-23_演示.txt',lines.join('\n'));await audit('林舒导出了今日通告','明确范围与版本 · 本地导出');toast('通告文件已导出');break;}
case 'export-handoff':download('B端后勤执行_登记快照.json',JSON.stringify({scope:'A/B本机共享服务4.0；按当前账号授权范围导出',exported_at:new Date().toISOString(),data:state},null,2),'application/json');await audit('林舒导出了后勤登记快照','指定本地演示数据 · 成功');toast('后勤登记快照已导出');break;
case 'reset-data':modal('恢复初始演示数据','仅恢复当前后勤原型中的演示记录。','<p class="muted" style="font-size:11px">项目、差旅、清单、费用和申请恢复为初始样本。</p>',button('取消','close')+button('恢复初始样本','confirm-reset','danger'));break;
case 'confirm-reset':state=seed();await persist();close();render();toast('演示数据已恢复');break;
case 'close':close();break;
}}catch(e){toast(e.message);}});
document.addEventListener('change',async ev=>{try{const el=ev.target;if(el.id==='project-type')document.querySelector('#rule-field').hidden=el.value!=='recurring';if(el.closest('#schedule-form'))updateEditConflicts();if(el.dataset.task){const p=project(el.dataset.project);p.tasks.find(t=>t.id===el.dataset.task).done=el.checked;await persist();el.closest('.task-check').classList.toggle('done',el.checked);el.closest('.task-check').querySelector('small').textContent=el.checked?'已完成':'待办';render();}if(el.dataset.prep){const c=state.preparations.find(c=>c.id===el.dataset.prep);c.done=el.checked;await audit('林舒'+(c.done?'完成':'重新打开')+'了准备事项',c.title+' · '+c.owner);render();}if(el.id==='check-filter'){checkFilter=el.value;render();}}catch(error){toast(error.message);}});
document.addEventListener('input',ev=>{if(ev.target.id==='global-search'){document.querySelector('.search-results')?.remove();const q=ev.target.value.trim();if(q){const matches=[...state.projects.filter(p=>p.name.includes(q)).map(p=>({title:p.name,sub:'后勤项目',action:'project-detail',id:p.id})),...state.travel.filter(t=>t.title.includes(q)).map(t=>({title:t.title,sub:'差旅与接送',action:'edit-record',kind:'travel',id:t.id})),...state.preparations.filter(t=>t.title.includes(q)).map(t=>({title:t.title,sub:'准备清单',action:'edit-record',kind:'preparations',id:t.id}))];const box=document.createElement('div');box.className='search-results';box.innerHTML=matches.length?matches.map(p=>`<a href="#${p.kind==='travel'?'travel':'projects'}" data-action="${p.action}" data-kind="${p.kind||''}" data-id="${p.id}">${esc(p.title)}<small>${p.sub}</small></a>`).join(''):'<div class="empty" style="padding:18px">可见执行事项中没有匹配项</div>';document.querySelector('.topbar').append(box);}}});
document.addEventListener('keydown',ev=>{if(ev.key==='Escape'){close();document.querySelector('.search-results')?.remove();}if(ev.key==='Tab'&&document.querySelector('[role="dialog"]')){const els=[...document.querySelector('[role="dialog"]').querySelectorAll('button:not(:disabled),input:not(:disabled),textarea:not(:disabled),select:not(:disabled),a[href]')].filter(e=>e.offsetParent!==null);if(!els.length)return;const first=els[0],last=els[els.length-1];if(ev.shiftKey&&document.activeElement===first){last.focus();ev.preventDefault();}else if(!ev.shiftKey&&document.activeElement===last){first.focus();ev.preventDefault();}}});
